namespace BlazorApi.CodeGeneration.CSharp;

/// <summary>Starts generated files with the common header.</summary>
internal static class FileWriter
{
    public static CodeWriter Start(GenerationPlan plan, string @namespace)
    {
        var writer = new CodeWriter();
        writer.Line("// <auto-generated>");
        writer.Line($"//     Generated by BlazorApi from the OpenAPI document \"{Sanitize(plan.Model.Title)}\" (version {Sanitize(plan.Model.Version)}).");
        writer.Line("//     Changes to this file are lost when the code is regenerated.");
        writer.Line("// </auto-generated>");
        writer.Line();
        writer.Line("#nullable enable");
        writer.Line("#pragma warning disable CS0612, CS0618 // Deprecated API elements are used by generated code.");
        writer.Line("#pragma warning disable CS1591 // Not every generated member has documentation in the OpenAPI document.");
        writer.Line();
        writer.Line($"namespace {@namespace};");
        writer.Line();
        return writer;
    }

    /// <summary>Removes characters that could end a line comment or confuse readers of the header.</summary>
    private static string Sanitize(string text)
    {
        var builder = new System.Text.StringBuilder(text.Length);
        foreach (var c in text)
        {
            builder.Append(char.IsControl(c) || c is (char)0x2028 or (char)0x2029 or (char)0x85 ? ' ' : c);
        }

        return builder.ToString();
    }
}
